using System.Text.Json;
using EqlTracker.Core;

internal static class QuestPetSlotTests
{
    internal static void Register(Action<string,Action> test)
    {
        void Check(bool value) { if (!value) throw new Exception("Quest / Pet slot assertion failed"); }
        void Test(string name, Action run) => test("Slot plan · " + name, run);
        ItemDefinition Weapon(string name, string[]? slots = null, bool two = false) => new() { Key=Identity.Key(name),Name=name,Slots=slots?.ToList()??["PRIMARY","SECONDARY"],Classes=["ALL"],MetadataComplete=true,TwoHanded=two,Stats=new(){["Damage"]=10,["Delay"]=20} };
        var blade=Weapon("Example blade");var primary=Weapon("Example primary",["PRIMARY"]);var two=Weapon("Example greatblade",["PRIMARY"],true);
        var shield=new ItemDefinition{Key="shield",Name="Example shield",Classes=["ALL"],Slots=["SECONDARY"],MetadataComplete=true,Stats=new(){["AC"]=10}};
        var armor=new ItemDefinition{Key="armor",Name="Example armor",Classes=["ALL"],Slots=["CHEST"],MetadataComplete=true,Stats=new(){["AC"]=20}};
        var wrist=new ItemDefinition{Key="wrist",Name="Example wrist",Classes=["ALL"],Slots=["WRIST"],MetadataComplete=true,Stats=new(){["AC"]=10}};
        var effectSource=Weapon("Example proc");effectSource.Effects=["proc: Example strike (Combat)"];
        var catalog=new Catalog{Items=[blade,primary,two,shield,armor,wrist,effectSource]};
        LoadoutProfile Owner()=>new(){Classes=["MAG","BRD","SHD"],Level=50,PetType="Earth",PetLevel=50};
        PetInventoryItem Entry(ItemDefinition item,int pos,int rank=4)=>new(){Id="copy-"+pos,ItemKey=item.Key,Name=item.Name,Position=pos,Slot="Storage",Rank=rank};
        PetBuild Build(params ItemDefinition[] items)=>new(){PetType="Earth",PetLevel=50,Items=items.Select((d,i)=>Entry(d,i+1)).ToList()};
        ExaltationAssignment Effect()=>new(){EffectId=ExaltationPlanner.EffectId(effectSource.Key,effectSource.Effects[0]),SourceName=effectSource.Name,Effect=effectSource.Effects[0],State="Socketed",DestinationRank=4};
        string Hand(EffectivePetEquipment e,string slot)=>e.Positions.First(p=>p.Slot==slot).Item?.ConfirmedItemKey??"";
        Test("migration is idempotent and keeps IDs ranks effects",()=>{var b=Build(blade);b.Items[0].Exaltations=[Effect()];PetSlotPlanning.Migrate(b,catalog);string first=JsonSerializer.Serialize(b);PetSlotPlanning.Migrate(b,catalog);Check(first==JsonSerializer.Serialize(b)&&b.SlotConfigurations.Single().Effects.Count==1&&b.Items[0].Rank==4&&b.Items[0].Id=="copy-1");});
        Test("reordering moves gear while effects remain in positions",()=>{var b=Build(blade,primary);b.Items[0].Exaltations=[Effect()];PetSlotPlanning.Migrate(b,catalog);Check(PetInventoryEditing.Reorder(b,b.Items[0].Id,2,out _));Check(b.SlotConfigurations.Single().Position==1&&b.Items.Single(i=>i.Position==1).Exaltations.Single().State=="Planned"&&b.Items.Single(i=>i.Position==2).Exaltations.Count==0);});
        Test("replacement retains slot effects as intent without socketing new ownership",()=>{var b=Build(blade);b.Items[0].Exaltations=[Effect()];PetSlotPlanning.Migrate(b,catalog);var replacement=Entry(primary,1);replacement.Id="replacement";b.Items=[replacement];PetSlotPlanning.Sync(b);Check(b.Items[0].Exaltations.Single().State=="Planned"&&b.SlotConfigurations[0].ObservedItemId=="copy-1");});
        Test("empty position can retain effects",()=>{var b=Build();PetSlotPlanning.SetEffects(b,2,[Effect()],"");Check(b.Items.Count==0&&b.SlotConfigurations.Single().Position==2);});
        Test("Dual wield disable frees position two and retains setup",()=>{var b=Build(primary,blade);PetSlotPlanning.Migrate(b,catalog);PetSlotPlanning.SetEffects(b,2,[Effect()],b.Items[1].Id);PetSlotPlanning.Toggle(b,false,catalog,7);Check(!b.DualWield&&b.Items.All(i=>i.Position!=2)&&b.DormantSecondary?.Id=="copy-2"&&b.DormantSecondaryConfiguration?.Effects.Count==1);PetSlotPlanning.Toggle(b,true,catalog,7);Check(b.DualWield&&b.Items.Count==2&&b.Items.Single(i=>i.Position==2).Id=="copy-2"&&b.DormantSecondary==null);});
        Test("restoration cannot overwrite armor",()=>{var b=Build(primary,blade);PetSlotPlanning.Migrate(b,catalog);PetSlotPlanning.Toggle(b,false,catalog,7);var a=Entry(armor,2);a.Id="new-armor";b.Items.Add(a);PetSlotPlanning.Toggle(b,true,catalog,7);Check(b.Items.Single(i=>i.Position==2).ItemKey==armor.Key&&b.DormantSecondary!=null&&PetSlotPlanning.Warnings(b,catalog,7).Any(s=>s.StartsWith("Too many armor")));});
        Test("armor compaction frees Secondary without losing entries",()=>{var b=Build(primary,armor,wrist);b.SlotConfigurationVersion=1;b.DualWield=true;PetSlotPlanning.CompactArmorAfterRemoval(b,catalog,7);Check(b.Items.Count==3&&b.Items.Single(i=>i.ItemKey==armor.Key).Position==3&&b.Items.Single(i=>i.ItemKey==wrist.Key).Position==4&&b.Items.All(i=>i.Position!=2));});
        Test("insufficient capacity does not evict armor",()=>{var b=Build(primary,armor,wrist);b.SlotConfigurationVersion=1;b.DualWield=true;var before=JsonSerializer.Serialize(b);PetSlotPlanning.CompactArmorAfterRemoval(b,catalog,3);Check(before==JsonSerializer.Serialize(b));});
        Test("toggle Undo restores complete slot configuration",()=>{var b=Build(primary,blade);PetSlotPlanning.Migrate(b,catalog);PetSlotPlanning.SetEffects(b,2,[Effect()],"copy-2");PetSlotPlanning.Toggle(b,false,catalog,7);Check(PetBuildEditing.Undo(b,out _)&&b.DualWield&&b.DormantSecondary==null&&b.Items.Count==2&&b.SlotConfigurations.Any(s=>s.Position==2&&s.Effects.Count==1));});
        Test("slot configuration survives JSON restart",()=>{var b=Build(primary,blade);PetSlotPlanning.Migrate(b,catalog);PetSlotPlanning.Toggle(b,false,catalog,7);var copy=JsonSerializer.Deserialize<PetBuild>(JsonSerializer.Serialize(b))!;Check(copy.DormantSecondary?.Id=="copy-2"&&!copy.DualWield&&copy.SlotConfigurationVersion==PetSlotPlanning.Version);});
        Test("two handed Primary disables Secondary without deleting it",()=>{var b=Build(two,blade);b.DualWield=true;b.SlotConfigurationVersion=1;var before=JsonSerializer.Serialize(b);var e=PetEquipmentInference.Build(b,Owner(),catalog);Check(Hand(e,"Primary")==two.Key&&Hand(e,"Secondary")==""&&JsonSerializer.Serialize(b)==before);});
        Test("primary-only item after flexible weapon does not swap",()=>{var b=Build(blade,primary);var e=PetEquipmentInference.Build(b,Owner(),catalog);Check(Hand(e,"Primary")==blade.Key&&Hand(e,"Secondary")=="");});
        Test("primary-only first allows flexible offhand",()=>{var b=Build(primary,blade);var e=PetEquipmentInference.Build(b,Owner(),catalog);Check(Hand(e,"Primary")==primary.Key&&Hand(e,"Secondary")==blade.Key);});
        Test("shield flexible then primary-only preserves first primary",()=>{var b=Build(shield,blade,primary);var e=PetEquipmentInference.Build(b,Owner(),catalog);Check(Hand(e,"Primary")==blade.Key&&Hand(e,"Secondary")==shield.Key);});
        Test("shield primary-only then flexible records observed offhand replacement",()=>{var b=Build(shield,primary,blade);var e=PetEquipmentInference.Build(b,Owner(),catalog);Check(Hand(e,"Primary")==primary.Key&&Hand(e,"Secondary")==blade.Key&&e.Totals.Notes.Any(n=>n.StartsWith("Conditional")));});
        Test("observed shield replacement keeps ratings Conditional",()=>{var b=Build(shield,primary,blade);var owner=Owner();var e=PetEquipmentInference.Build(b,owner,catalog);var session=new LoadoutEvaluationSession(catalog,owner,true,GearScorer.Defaults["Pet DPS"],e.Positions,e.Positions,petInventory:b);Check(session.CompareBuild(e.Positions).Status=="Conditional");});
        Test("third two-hander cannot invent combined ratio winner",()=>{var b=Build(primary,blade,two);var e=PetEquipmentInference.Build(b,Owner(),catalog);Check(Hand(e,"Primary")==primary.Key&&Hand(e,"Secondary")==blade.Key&&e.Totals.Notes.Any(n=>n.StartsWith("Conditional")));});
        Test("paired wrists are valid but excess chest armor warns",()=>{var b=Build(wrist,wrist);PetSlotPlanning.Migrate(b,catalog);Check(!PetSlotPlanning.Warnings(b,catalog,7).Any(n=>n.Contains("duplicate armor")));b=Build(armor,armor);Check(PetSlotPlanning.Warnings(b,catalog,7).Any(n=>n.Contains("duplicate armor")));});
        Test("rank locked configured proc is inactive without excluding weapon",()=>{var b=Build(primary);PetSlotPlanning.SetEffects(b,1,[Effect()],"copy-1");Check(PetInventoryEditing.SetRank(b,"copy-1",0,catalog,out _));var e=PetEquipmentInference.Build(b,Owner(),catalog);Check(Hand(e,"Primary")==primary.Key&&e.Totals.Procs.Count==0&&e.Totals.Notes.Any(n=>n.StartsWith("Inactive")));});
        Test("incompatible retained effects do not exclude armor",()=>{var b=Build(armor);PetSlotPlanning.SetEffects(b,1,[Effect()],"copy-1");var e=PetEquipmentInference.Build(b,Owner(),catalog);Check(e.Totals.Stats.GetValueOrDefault("AC")==28&&e.Totals.Notes.Any(n=>n.StartsWith("Inactive")));});
        Test("catalog proc requires explicit selection without recording a transfer",()=>{var b=Build(effectSource,primary);var e=PetEquipmentInference.Build(b,Owner(),catalog);Check(e.Totals.Procs.Count==0&&b.SlotConfigurations.Count==0);PetSlotPlanning.SetEffects(b,1,[Effect()],b.Items[0].Id);e=PetEquipmentInference.Build(b,Owner(),catalog);Check(e.Totals.Procs.Any(n=>n.Contains("Example strike"))&&b.Items[0].TransferredOutEffects.Count==0);});
        Test("reward search covers aliases alternatives and case",()=>{var reward=new ItemDefinition{Key="reward",Name="Singing Short Sword",Aliases=["Bard singing blade"]};var c=new Catalog{Items=[reward]};var q=new QuestDefinition{Name="Bard Epic Quest",RewardAlternatives=[["reward"]]};Check(QuestPresentation.Matches(q,c,"singing")&&QuestPresentation.Matches(q,c,"BARD SINGING")&&!QuestPresentation.Matches(q,c,"not-a-reward"));});
        Test("contextual headings remove only repeated prefix",()=>{var q=new QuestDefinition{Name="Bard Epic Quest"};Check(QuestPresentation.StepHeading(q,new(){Name="Bard Epic Quest: Gather scales"})=="Gather scales"&&QuestPresentation.StepHeading(q,new(){Name="Make a lute"})=="Make a lute");});
        Test("editing an item position does not move configured effects",()=>{var b=Build(primary);b.Items[0].Exaltations=[Effect()];PetSlotPlanning.Migrate(b,catalog);var moved=EquipmentPositions.Copy(b.Items[0]);moved.Position=3;Check(PetInventoryEditing.Put(b,moved,1,false,out _));Check(b.SlotConfigurations.Single().Position==1&&b.Items.Single().Position==3&&b.Items.Single().Exaltations.Count==0);});
        Test("new item cannot inherit socketing evidence through Put",()=>{var b=Build(primary);b.Items[0].Exaltations=[Effect()];PetSlotPlanning.Migrate(b,catalog);var changed=Entry(blade,1);changed.Exaltations=[Effect()];Check(PetInventoryEditing.Put(b,changed,1,false,out _));Check(b.Items.Single().Exaltations.Single().State=="Planned");});
        Test("default DPS ratio outweighs nine DEX when all else equal",()=>{var weights=GearScorer.Defaults["Pet DPS"];double ratio=.15*weights["Ratio"],dex=9*weights["DEX"],agi=8*weights.GetValueOrDefault("AGI");Check(ratio==15&&dex==4.5&&agi==0&&ratio>dex+agi);});
        Test("adding a weapon changes replacement baseline without ownership mutation",()=>{var b=Build(primary);PetSlotPlanning.Migrate(b,catalog);b.DualWield=true;var p=Owner();var first=PetEquipmentInference.Build(b,p,catalog);var physical=new InventorySnapshot();PetInventoryEditing.Add(b,blade,null,7,null,false,out _,out _);var second=PetEquipmentInference.Build(b,p,catalog);Check(Hand(first,"Secondary")==""&&Hand(second,"Secondary")==blade.Key&&physical.Entries.Count==0);});
    }
}
